        'publications.eyebrow': "Forschung & Entwicklung",
        'publications.lede': "Eine Übersicht unserer aktuellen Projekte, veröffentlichten Arbeiten und offenen Beiträge. Jeder Eintrag verlinkt auf den vollständigen Beitrag bzw. das zugehörige Repository.",
        'publications.filter_label': "Nach Kategorie filtern",
